package app.sleepscreen.tv;
import android.app.Activity;import android.os.Bundle;import android.view.KeyEvent;import android.graphics.Color;import android.widget.*;
public class MapperActivity extends Activity {
 private TextView status;private boolean listening=false;
 protected void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(Ui.dp(this,48),Ui.dp(this,36),Ui.dp(this,48),Ui.dp(this,36));root.setBackgroundColor(0xff0b0d12);TextView t=Ui.text(this,30,Color.WHITE);t.setText("Remote button");root.addView(t);status=Ui.text(this,18,Color.WHITE);root.addView(status);TextView capture=Ui.row(root,700);capture.setText("Choose button");capture.setOnClickListener(v->{listening=true;status.setText("Press the button you want to use. Back cancels.");});TextView clear=Ui.row(root,700);clear.setText("Remove mapping");clear.setOnClickListener(v->{getSharedPreferences("mapping",0).edit().clear().apply();update();});setContentView(root);update();}
 void update(){int key=getSharedPreferences("mapping",0).getInt("key",0);status.setText(key==0?"No button assigned. Enable Sleep Screen Remote under Accessibility first.":"Assigned: "+KeyEvent.keyCodeToString(key)+". Other button mappers may conflict.");}
 @Override public boolean dispatchKeyEvent(KeyEvent e){if(listening&&e.getAction()==KeyEvent.ACTION_DOWN){int k=e.getKeyCode();if(k==KeyEvent.KEYCODE_BACK){listening=false;update();return true;}if(k==KeyEvent.KEYCODE_UNKNOWN||k==KeyEvent.KEYCODE_HOME||k==KeyEvent.KEYCODE_POWER||k==KeyEvent.KEYCODE_DPAD_CENTER||k==KeyEvent.KEYCODE_DPAD_UP||k==KeyEvent.KEYCODE_DPAD_DOWN||k==KeyEvent.KEYCODE_DPAD_LEFT||k==KeyEvent.KEYCODE_DPAD_RIGHT||k==KeyEvent.KEYCODE_VOLUME_UP||k==KeyEvent.KEYCODE_VOLUME_DOWN){status.setText("That button cannot be safely assigned. Choose another, or press Back.");return true;}getSharedPreferences("mapping",0).edit().putInt("key",k).putInt("scan",e.getScanCode()).apply();listening=false;update();return true;}return super.dispatchKeyEvent(e);}
}